# ruff: noqa: E501
"""Individually reviewed family video plans, independent of FAQ answer steps.

Sources: app-help.js, index.html, app-store.js, app-shell.js, app-bank.js,
app-support.js, bot support/keyboards, and screens.py/external.py fixtures.
External bot scenes are illustrations, not recordings of a live MAX session.
No inferred steps, automatic outcomes, support tails, or account-picker scenes.
"""


def _plan(review_note, *steps):
    """Expand only the explicitly authored tuples; never append editorial content."""
    return {
        "video_steps": [
            {"text": text, "shot": shot, **({"action": action[0]} if action else {})}
            for text, shot, *action in steps
        ],
        "review_note": review_note,
    }


